const webhook = $('Webhook').first().json;

const question =
  webhook.body?.question ??
  webhook.question ??
  '';

function normalizeText(value) {
  return String(value ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\p{L}\p{N}\s-]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const stopWords = new Set([
  'a',
  'o',
  'as',
  'os',
  'um',
  'uma',
  'uns',
  'umas',
  'de',
  'da',
  'do',
  'das',
  'dos',
  'em',
  'no',
  'na',
  'nos',
  'nas',
  'para',
  'por',
  'com',
  'sem',
  'sobre',
  'entre',
  'qual',
  'quais',
  'como',
  'onde',
  'quando',
  'quem',
  'que',
  'e',
  'ou',
  'se',
  'tem',
  'ter',
  'existem',
  'existe',
  'informe',
  'informar',
  'informacao',
  'informacoes',
  'liste',
  'listar',
  'mostre',
  'mostrar'
]);

const normalizedQuestion = normalizeText(question);

const questionTerms = normalizedQuestion
  .split(/\s+/)
  .filter(term => term.length > 2)
  .filter(term => !stopWords.has(term));

const rows = $input.all().map(item => {
  const row = item.json;

  return {
    categoryId: row.categoryId ?? null,
    categoryName: row.categoryName ?? '',
    categoryDescription: row.categoryDescription ?? '',
    subcategoryId: row.subcategoryId ?? null,
    subcategoryName: row.subcategoryName ?? '',
    subcategoryDescription: row.subcategoryDescription ?? '',

    normalizedCategoryName: normalizeText(row.categoryName),
    normalizedCategoryDescription: normalizeText(
      row.categoryDescription
    ),
    normalizedSubcategoryName: normalizeText(
      row.subcategoryName
    ),
    normalizedSubcategoryDescription: normalizeText(
      row.subcategoryDescription
    )
  };
});

const scoredRows = rows.map(row => {
  let categoryScore = 0;
  let subcategoryScore = 0;

  /*
   * Correspondência direta com os nomes.
   */
  if (
    row.normalizedCategoryName &&
    normalizedQuestion.includes(row.normalizedCategoryName)
  ) {
    categoryScore += 80;
  }

  if (
    row.normalizedSubcategoryName &&
    normalizedQuestion.includes(row.normalizedSubcategoryName)
  ) {
    subcategoryScore += 140;
  }

  /*
   * Correspondência termo a termo.
   */
  for (const term of questionTerms) {
    if (
      row.normalizedCategoryName &&
      row.normalizedCategoryName.includes(term)
    ) {
      categoryScore += 25;
    }

    if (
      row.normalizedCategoryDescription &&
      row.normalizedCategoryDescription.includes(term)
    ) {
      categoryScore += 12;
    }

    if (
      row.normalizedSubcategoryName &&
      row.normalizedSubcategoryName.includes(term)
    ) {
      subcategoryScore += 35;
    }

    if (
      row.normalizedSubcategoryDescription &&
      row.normalizedSubcategoryDescription.includes(term)
    ) {
      subcategoryScore += 20;
    }
  }

  return {
    categoryId: row.categoryId,
    categoryName: row.categoryName,
    categoryDescription: row.categoryDescription,

    subcategoryId: row.subcategoryId,
    subcategoryName: row.subcategoryName,
    subcategoryDescription: row.subcategoryDescription,

    categoryScore,
    subcategoryScore,
    totalScore: categoryScore + subcategoryScore
  };
});

/*
 * Melhor linha completa: categoria + possível subcategoria.
 */
scoredRows.sort((a, b) => {
  if (b.totalScore !== a.totalScore) {
    return b.totalScore - a.totalScore;
  }

  return b.subcategoryScore - a.subcategoryScore;
});

const bestRow =
  scoredRows.length > 0 && scoredRows[0].totalScore > 0
    ? scoredRows[0]
    : null;

/*
 * Pode existir correspondência com a categoria, mas nenhuma
 * subcategoria específica.
 *
 * Nesse caso mantemos a categoria e deixamos subcategoryId nulo.
 */
let selectedCategory = null;
let selectedSubcategory = null;

if (bestRow) {
  selectedCategory = {
    id: bestRow.categoryId,
    name: bestRow.categoryName,
    description: bestRow.categoryDescription,
    score: bestRow.categoryScore
  };

  if (
    bestRow.subcategoryId &&
    bestRow.subcategoryScore > 0
  ) {
    selectedSubcategory = {
      id: bestRow.subcategoryId,
      name: bestRow.subcategoryName,
      description: bestRow.subcategoryDescription,
      score: bestRow.subcategoryScore
    };
  }
}

/*
 * Termos usados na busca SQL.
 */
const searchTerms = [...new Set(questionTerms)]
  .filter(term => term.length > 3)
  .slice(0, 8);

/*
 * Candidatos servem para depuração.
 * Não precisam ser enviados ao frontend.
 */
const candidates = scoredRows
  .filter(row => row.totalScore > 0)
  .slice(0, 5)
  .map(row => ({
    categoryId: row.categoryId,
    categoryName: row.categoryName,
    subcategoryId: row.subcategoryId,
    subcategoryName: row.subcategoryName,
    categoryScore: row.categoryScore,
    subcategoryScore: row.subcategoryScore,
    totalScore: row.totalScore
  }));

return [
  {
    json: {
      question,

      categoryId: selectedCategory?.id ?? null,
      categoryName: selectedCategory?.name ?? null,
      categoryDescription:
        selectedCategory?.description ?? null,

      subcategoryId: selectedSubcategory?.id ?? null,
      subcategoryName: selectedSubcategory?.name ?? null,
      subcategoryDescription:
        selectedSubcategory?.description ?? null,

      searchTerms,
      classificationCandidates: candidates
    }
  }
];

const items = $input.all();

const classification =
  $('Classificar pergunta').first().json;

const question = classification.question ?? '';

const categoryId =
  classification.categoryId ?? null;

const categoryName =
  classification.categoryName ?? null;

const categoryDescription =
  classification.categoryDescription ?? null;

const subcategoryId =
  classification.subcategoryId ?? null;

const subcategoryName =
  classification.subcategoryName ?? null;

const subcategoryDescription =
  classification.subcategoryDescription ?? null;

/*
 * Cada item é um chunk retornado pelo PostgreSQL.
 */
const contextChunks = items.map((item, index) => {
  const row = item.json;

  return {
    index: index + 1,

    documentId: row.documentId,
    documentTitle: row.documentTitle,

    sectorId: row.sectorId ?? null,
    sectorName: row.sectorName ?? null,

    categoryId: row.categoryId ?? null,
    categoryName: row.categoryName ?? null,
    categoryDescription:
      row.categoryDescription ?? null,

    subcategoryId: row.subcategoryId ?? null,
    subcategoryName: row.subcategoryName ?? null,
    subcategoryDescription:
      row.subcategoryDescription ?? null,

    vigencyDate: row.vigencyDate ?? null,

    chunkOrder: row.chunkOrder,
    relevance: row.relevance ?? 0,

    text: row.chunkText ?? ''
  };
});

/*
 * Texto enviado à OpenAI.
 */
const context = contextChunks
  .map(source => {
    return `
[Fontes ${source.index}]

Documento: ${source.documentTitle || 'Não informado'}
Setor: ${source.sectorName || 'Não informado'}
Categoria: ${source.categoryName || 'Não informada'}
Subcategoria: ${source.subcategoryName || 'Não informada'}
Data de vigência: ${source.vigencyDate || 'Não informada'}
Ordem do trecho: ${source.chunkOrder}
Relevância calculada: ${source.relevance}

Trecho documental:
${source.text}
`.trim();
  })
  .join('\n\n------------------------------\n\n');

/*
 * Fontes únicas para o frontend.
 *
 * Um documento pode ter vários chunks, mas deve gerar somente
 * um card em "Fontes consultadas".
 */
const uniqueSourcesMap = new Map();

for (const source of contextChunks) {
  if (!source.documentId) {
    continue;
  }

  const existing =
    uniqueSourcesMap.get(source.documentId);

  if (!existing) {
    uniqueSourcesMap.set(source.documentId, {
      documentId: source.documentId,
      documentTitle: source.documentTitle,

      sectorId: source.sectorId,
      sectorName: source.sectorName,

      categoryId: source.categoryId,
      categoryName: source.categoryName,

      subcategoryId: source.subcategoryId,
      subcategoryName: source.subcategoryName,

      vigencyDate: source.vigencyDate,

      relevance: source.relevance
    });

    continue;
  }

  /*
   * Preserva a maior relevância entre os chunks do documento.
   */
  if (
    Number(source.relevance) >
    Number(existing.relevance)
  ) {
    existing.relevance = source.relevance;
  }
}

const sources = [...uniqueSourcesMap.values()]
  .sort((a, b) => {
    return Number(b.relevance) - Number(a.relevance);
  })
  .map((source, index) => ({
    index: index + 1,

    documentId: source.documentId,
    documentTitle: source.documentTitle,

    sectorId: source.sectorId,
    sectorName: source.sectorName,

    categoryId: source.categoryId,
    categoryName: source.categoryName,

    subcategoryId: source.subcategoryId,
    subcategoryName: source.subcategoryName,

    vigencyDate: source.vigencyDate
  }));

return [
  {
    json: {
      question,

      classification: {
        categoryId,
        categoryName,
        categoryDescription,

        subcategoryId,
        subcategoryName,
        subcategoryDescription
      },

      context,
      sources,

      diagnostic: {
        totalChunks: contextChunks.length,
        totalDocuments: sources.length
      }
    }
  }
];

const ctx = $('Montar contexto').first().json;
const prompt = $('Aplicar prompt carregado').first().json || {};
const answer = $json.output?.[0]?.content?.[0]?.text ?? '';
const sources = (ctx.sources || []).map((s) => ({
  ...s,
  expirationDate: s.expirationDate ?? s.vigencyDate ?? null,
}));
const requestId = $('Normalizar request').first().json.requestId;
let rankingMeta = null;
let rankedDocumentIds = [];
let fallbackUsed = false;
let retrievalConfigVersion = null;
let modeOverrideUsed = false;
try {
  const ranked = $('Resolver ranking final').all().map(i => i.json).filter(Boolean);
  if (ranked.length) {
    rankingMeta = ranked[0].rankingMetadata || null;
    fallbackUsed = !!ranked[0].fallbackUsed || !!(rankingMeta && rankingMeta.fallbackUsed);
    retrievalConfigVersion = ranked[0].retrievalConfigVersion || (rankingMeta && rankingMeta.versionLabel) || null;
    rankedDocumentIds = ranked.map(r => r.documentId || r.document_id).filter(Boolean);
  }
} catch (_) {}
try {
  const cfg = $('Carregar retrieval config').first().json || {};
  modeOverrideUsed = !!cfg.modeOverrideUsed;
  if (!retrievalConfigVersion) retrievalConfigVersion = cfg.versionLabel || null;
} catch (_) {}
const retrievalMeta = {
  mode: (rankingMeta && rankingMeta.mode) || null,
  versionLabel: retrievalConfigVersion,
  candidateCount: rankingMeta && rankingMeta.candidateCount != null ? Number(rankingMeta.candidateCount) : null,
  selectedCount: rankingMeta && rankingMeta.selectedCount != null ? Number(rankingMeta.selectedCount) : rankedDocumentIds.length,
  durationMs: rankingMeta && rankingMeta.durationMs != null ? Number(rankingMeta.durationMs) : null,
  fallbackUsed,
  modeOverrideUsed,
  rankedDocumentIds,
};
return [{
  json: {
    data: {
      question: ctx.question,
      answer,
      sources,
      classification: ctx.classification,
      retrievalMeta,
    },
    statusCode: 200,
    requestId,
    promptMeta: {
      promptVersionId: prompt.promptVersionId || null,
      promptCode: prompt.promptCode || null,
      versionNumber: prompt.versionNumber != null ? prompt.versionNumber : null,
      contentHash: prompt.contentHash || null,
      modelName: prompt.modelName || null,
    },
  },
}];

const ctx = $('Montar contexto').first().json || {};
const loaded = $input.first().json || {};
if (!loaded.ok) {
  throw new Error('Falha ao carregar prompt ativo: ' + (loaded.code || 'PROMPT_NOT_FOUND'));
}
const cls = ctx.classification || {};
const userContent = 'Pergunta do usuário:\n\n' + (ctx.question || '') +
  '\n\nCategoria identificada:\n\n' + (cls.categoryName || 'Não identificada') +
  '\n\nDescrição da categoria:\n\n' + (cls.categoryDescription || 'Não informada') +
  '\n\nSubcategoria identificada:\n\n' + (cls.subcategoryName || 'Não identificada') +
  '\n\nDescrição da subcategoria:\n\n' + (cls.subcategoryDescription || 'Não informada') +
  '\n\nContexto documental recuperado:\n\n' + (ctx.context || '') +
  '\n\nResponda exclusivamente com base no contexto documental acima.';

return [{
  json: {
    ...ctx,
    systemContent: loaded.content,
    userContent,
    modelName: loaded.modelName || 'gpt-4.1-mini',
    temperature: loaded.temperature != null ? loaded.temperature : 0.1,
    maxTokens: loaded.maxTokens != null ? loaded.maxTokens : 800,
    promptVersionId: loaded.promptVersionId || null,
    promptDefinitionId: loaded.promptDefinitionId || null,
    promptCode: loaded.promptCode || null,
    versionNumber: loaded.versionNumber != null ? loaded.versionNumber : null,
    contentHash: loaded.contentHash || null,
  },
}];

const cls=$('Extrair vetor pergunta').first().json||{};
const items=$input.all().map(i=>i.json);
let vectorHits=[];
const textRows=[];
for(const it of items){
  if(Array.isArray(it.hits)) vectorHits=it.hits;
  else if(it.chunkText||it.documentId) textRows.push(it);
}
try{ if(!vectorHits.length) vectorHits=($('Busca vetorial Qdrant').first().json.hits)||[]; }catch(_){}
const wV=0.65,wT=0.35;
const maxText=Math.max(1,...textRows.map(r=>Number(r.relevance||0)));
const byKey=new Map();
function keyOf(docId,order){return String(docId)+':'+String(order);}
for(const h of vectorHits){
  const k=keyOf(h.documentId,h.chunkIndex);
  byKey.set(k,{documentId:h.documentId,documentTitle:h.documentTitle,sectorId:h.sectorId,categoryId:h.categoryId,subcategoryId:h.subcategoryId,chunkIndex:h.chunkIndex,chunkKind:h.chunkKind,sheetName:h.sheetName,ocrQuality:h.ocrQuality,vectorScore:Number(h.vectorScore||0),textScore:0,chunkText:null,versionId:h.documentVersionId,isCurrent:h.isCurrent!==false});
}
for(const r of textRows){
  const k=keyOf(r.documentId,r.chunkOrder);
  const textScore=Number(r.relevance||0)/maxText;
  const row=byKey.get(k)||{documentId:r.documentId,documentTitle:r.documentTitle,sectorId:r.sectorId,categoryId:r.categoryId,subcategoryId:r.subcategoryId,chunkIndex:r.chunkOrder,chunkKind:r.chunkKind,sheetName:r.sheetName,ocrQuality:null,vectorScore:0,textScore:0,chunkText:null,versionId:r.versionId,isCurrent:true};
  row.textScore=Math.max(row.textScore||0,textScore);
  row.chunkText=r.chunkText||row.chunkText;
  row.documentTitle=r.documentTitle||row.documentTitle;
  row.sectorName=r.sectorName; row.categoryName=r.categoryName; row.subcategoryName=r.subcategoryName;
  row.categoryDescription=r.categoryDescription; row.subcategoryDescription=r.subcategoryDescription;
  row.vigencyDate=r.vigencyDate; row.documentUpdatedAt=r.documentUpdatedAt; row.versionNumber=r.versionNumber; row.versionId=r.versionId||row.versionId;
  byKey.set(k,row);
}
const catId=cls.categoryId||null, subId=cls.subcategoryId||null;
const merged=[];
for(const row of byKey.values()){
  if(!row.chunkText) continue;
  let boost=0;
  if(subId&&row.subcategoryId===subId) boost+=0.15; else if(catId&&row.categoryId===catId) boost+=0.10;
  const ocr=String(row.ocrQuality||'').toUpperCase();
  if(ocr==='EXCELLENT'||ocr==='GOOD') boost+=0.05;
  if(String(row.chunkKind||'').toLowerCase()==='tabular') boost+=0.05;
  if(row.isCurrent!==false) boost+=0.05;
  const vectorNorm=Math.max(0,Math.min(1,Number(row.vectorScore||0)));
  const textNorm=Math.max(0,Math.min(1,Number(row.textScore||0)));
  const mergedScore=wV*vectorNorm+wT*textNorm+boost;
  merged.push({documentId:row.documentId,documentTitle:row.documentTitle,sectorId:row.sectorId,sectorName:row.sectorName,categoryId:row.categoryId,categoryName:row.categoryName,categoryDescription:row.categoryDescription,subcategoryId:row.subcategoryId,subcategoryName:row.subcategoryName,subcategoryDescription:row.subcategoryDescription,vigencyDate:row.vigencyDate,documentUpdatedAt:row.documentUpdatedAt,versionNumber:row.versionNumber,versionId:row.versionId,chunkOrder:row.chunkIndex,chunkText:row.chunkText,chunkKind:row.chunkKind,sheetName:row.sheetName,relevance:Math.round(mergedScore*1000),vectorScore:vectorNorm,textScore:textNorm,mergedScore,retrievalMode:vectorHits.length?'hybrid':'text_fallback'});
}
merged.sort((a,b)=>b.mergedScore-a.mergedScore);
const candidatePool=30;
const top=merged.slice(0,candidatePool);
if(!top.length) return textRows.slice(0,12).map(r=>({json:{...r,retrievalMode:'text_fallback'}}));
return top.map((r,i)=>({json:{...r, hybridRank:i+1, candidatePool}}));

const cfgNode=$('Carregar retrieval config').first().json||{};
const cfg=cfgNode.configuration||{};
const mode=String(cfgNode.mode||cfg.mode||'HYBRID').toUpperCase();
const finalLimit=Math.min(Math.max(Number(cfg.finalLimit||12)||12,1),20);
const candidates=$('Merge híbrido').all().map(i=>i.json).filter(r=>r&&(r.chunkText||r.documentId));
const classification=$('Classificar pergunta').first().json||{};
const question=String(classification.question||'');
const useRerank=mode==='HYBRID_RERANK';
return [{json:{
  mode, useRerank, finalLimit,
  versionLabel: cfgNode.versionLabel||'hybrid-v1',
  configurationJson: JSON.stringify({...cfg, mode, versionLabel: cfgNode.versionLabel||null}),
  classificationJson: JSON.stringify({
    categoryId: classification.categoryId||null,
    subcategoryId: classification.subcategoryId||null,
    categoryName: classification.categoryName||null,
    subcategoryName: classification.subcategoryName||null,
    searchTerms: classification.searchTerms||[],
  }),
  candidatesJson: JSON.stringify(candidates),
  candidates,
  question,
  requestId: $('Normalizar request').first().json.requestId||'',
  userId: $('Validar auth').first().json.userId||'',
  sessionId: $('Validar auth').first().json.sessionId||'',
}}];

const prep=$('Preparar seleção retrieval').first().json||{};
const mode=String(prep.mode||'HYBRID').toUpperCase();
const finalLimit=Number(prep.finalLimit||12)||12;
const hybridCandidates=Array.isArray(prep.candidates)?prep.candidates:[];
let ranked=[];
let fallbackUsed=false;
let rankingMetadata={mode, fallbackUsed:false, selectedCount:0, durationMs:0};
if(mode==='HYBRID_RERANK'){
  const rr=$input.first().json||{};
  if(rr.ok===true && Array.isArray(rr.rankedCandidates) && rr.rankedCandidates.length){
    ranked=rr.rankedCandidates;
    rankingMetadata=rr.rankingMetadata||rankingMetadata;
  } else {
    fallbackUsed=true;
    rankingMetadata={mode:'HYBRID_FALLBACK', fallbackUsed:true, selectedCount:0, durationMs:0, error:rr.error||'rerank_failed'};
    ranked=hybridCandidates.slice(0, finalLimit).map((c,i)=>({...c, rerankPosition:i+1, rerankScore:c.mergedScore||0, selectionReason:'hybrid_fallback', retrievalMode:'hybrid_fallback'}));
    try {
      // audit fallback is best-effort via metadata on response; dedicated audit optional
    } catch(_){}
  }
} else {
  ranked=hybridCandidates.slice(0, finalLimit).map((c,i)=>({...c, rerankPosition:i+1, rerankScore:c.mergedScore||0, selectionReason:'hybrid', retrievalMode:c.retrievalMode||'hybrid'}));
  rankingMetadata={mode, fallbackUsed:false, selectedCount:ranked.length, durationMs:0, versionLabel:prep.versionLabel||null};
}
rankingMetadata.fallbackUsed=fallbackUsed||!!rankingMetadata.fallbackUsed;
rankingMetadata.selectedCount=ranked.length;
rankingMetadata.versionLabel=prep.versionLabel||rankingMetadata.versionLabel||null;
return ranked.map((r,i)=>({json:{...r, rankingMetadata, retrievalConfigVersion:prep.versionLabel||null, fallbackUsed:rankingMetadata.fallbackUsed}}));
